import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, DirectionalLight } from 'three/webgpu';
import { gsap } from 'gsap';
import { uv, mix, color } from 'three/tsl';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // ---------- Backdrop (vertical gradient) ----------
  const backdropGeom = new ctx.THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color('#ff4450'), color('#c1121f'), uv().y);
  const backdropMesh = new ctx.THREE.Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  group.add(backdropMesh);

  // ---------- Card dimensions ----------
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const BORDER_THICK = 0.006;
  const PADDING = 0.5; // 2 × base unit (0.25)

  // ---------- Border (hairline) ----------
  const borderGeom = new ctx.THREE.PlaneGeometry(CARD_W + BORDER_THICK * 2, CARD_H + BORDER_THICK * 2);
  const borderMat = new MeshBasicNodeMaterial({ color: new Color('#2a2a33') });
  const borderMesh = new ctx.THREE.Mesh(borderGeom, borderMat);
  borderMesh.position.z = 0.001;
  group.add(borderMesh);

  // ---------- Card background (responsive to light) ----------
  const bgGeom = new ctx.THREE.PlaneGeometry(CARD_W, CARD_H);
  const bgMat = new MeshStandardNodeMaterial({
    color: new Color('#16161d'),
    metalness: 0.0,
    roughness: 0.8,
  });
  const bgMesh = new ctx.THREE.Mesh(bgGeom, bgMat);
  bgMesh.position.z = 0.002;
  group.add(bgMesh);

  // ---------- Header strip (machined) ----------
  const HEADER_H = 0.08;
  const headerGeom = new ctx.THREE.PlaneGeometry(CARD_W, HEADER_H);
  const headerMat = new MeshStandardNodeMaterial({
    color: new Color('#16161d'),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
  });
  const headerMesh = new ctx.THREE.Mesh(headerGeom, headerMat);
  headerMesh.position.set(0, CARD_H / 2 - HEADER_H / 2, 0.003);
  group.add(headerMesh);

  // ---------- Rim light (accent) ----------
  const rimLight = new ctx.THREE.DirectionalLight(new Color('#ff2a38'), 0.8);
  rimLight.position.set(0, -1, 1);
  group.add(rimLight);

  // ---------- Text handling ----------
  const textGroup = new ctx.THREE.Group();
  group.add(textGroup);

  const addText = (content, opts, y) => {
    const txt = ctx.fontAtlas.createText(content, {
      ...opts,
      maxWidthPx: CARD_W * 100, // prevent overflow
    });
    txt.position.set(0, y, 0.004);
    // ensure transparency for animation
    txt.traverse((obj) => {
      if (obj.material) {
        obj.material.transparent = true;
        obj.material.opacity = 1;
      }
    });
    textGroup.add(txt);
    return txt;
  };

  const topY = CARD_H / 2 - PADDING;

  // Tier name
  const tierY = topY - 0.31;
  addText('ATELIER RESERVE', {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.08,
  }, tierY);

  // Price
  const priceY = tierY - 0.55;
  addText('$480', {
    fontSize: 62,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: -0.01,
  }, priceY);

  // Caption
  const captionY = priceY - 0.4;
  addText('PER MONTH, BILLED ANNUALLY', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.12,
  }, captionY);

  // Feature rows (staggered fade‑up)
  const featureStartY = captionY - 0.6;
  const FEATURE_H = 0.375;
  const HAIRLINE = 0.006;
  const featureTexts = [];
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing',
  ];
  features.forEach((txt, i) => {
    const y = featureStartY - i * (FEATURE_H + HAIRLINE);
    const txtObj = addText(txt, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 0,
    }, y);
    txtObj.visible = false;
    txtObj.position.y += 0.2;
    featureTexts.push(txtObj);
  });

  // CTA row (gradient + emissive)
  const ctaY = -CARD_H / 2 + PADDING + 0.18;
  const ctaGeom = new ctx.THREE.PlaneGeometry(1.4, 0.36);
  const ctaMat = new MeshStandardNodeMaterial({
    metalness: 0.3,
    roughness: 0.5,
    clearcoat: 0.2,
    emissiveIntensity: 1.5,
  });
  ctaMat.colorNode = mix(color('#ff4450'), color('#c1121f'), uv().y);
  ctaMat.emissiveNode = color('#ff2a38');
  const ctaMesh = new ctx.THREE.Mesh(ctaGeom, ctaMat);
  ctaMesh.position.set(0, ctaY, 0.004);
  group.add(ctaMesh);

  const ctaLabel = addText('JOIN THE RESERVE', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.08,
  }, ctaY);

  // ---------- Animations ----------
  const timelines = [];

  // Card mount (weighted‑settle)
  const mountTL = gsap.timeline({ defaults: { ease: 'power4.out' } });
  mountTL.fromTo(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9 }
  );
  timelines.push(mountTL);

  // Feature rows stagger fade‑up
  const featureTL = gsap.timeline({ defaults: { ease: 'power2.out' } });
  featureTexts.forEach((mesh, i) => {
    featureTL.fromTo(
      mesh.position,
      { y: mesh.position.y },
      {
        y: mesh.position.y - 0.2,
        duration: 0.5,
        onStart: () => { mesh.visible = true; },
        onComplete: () => {
          mesh.traverse((obj) => {
            if (obj.material) obj.material.opacity = 1;
          });
        },
        delay: i * 0.08,
      }
    );
  });
  timelines.push(featureTL);

  // CTA press interaction
  const pressTL = gsap.timeline({ paused: true });
  pressTL.to(ctaMesh.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.275)',
  });

  group.userData.handlers = {
    pointerdown: () => pressTL.restart(),
    pointerup: () => pressTL.reverse(),
  };

  // ---------- Cleanup ----------
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    pressTL.kill();
    // dispose geometries
    borderGeom.dispose();
    bgGeom.dispose();
    headerGeom.dispose();
    ctaGeom.dispose();
    backdropGeom.dispose();
    // dispose materials
    borderMat.dispose();
    bgMat.dispose();
    headerMat.dispose();
    ctaMat.dispose();
    backdropMat.dispose();
    // dispose light
    rimLight.dispose &&    // dispose any mesh materials/textures
    group.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  // Apply any cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const primitiveFn = ctx.primitives[p.name];
      if (primitiveFn) {
        const inst = primitiveFn(group, p.params);
        const prevCleanup = group.userData.cleanup;
        group.userData.cleanup = () => {
          if (inst && typeof inst.cleanup === 'function') inst.cleanup();
          if (prevCleanup) prevCleanup();
        };
      }
    });
  }

  return group;
}
